create extension if not exists pgcrypto;
create type public.user_role as enum ('SURVIVOR','COUNSELLOR','DISTRICT_ADMIN','STATE_ADMIN','NATIONAL_ADMIN');
create type public.monitoring_state as enum ('active','paused','stopped');
create type public.alert_status as enum ('NEW','ACKNOWLEDGED','ASSIGNED','RESOLVED');
create type public.priority_level as enum ('P1','P2','P3','P4');
create type public.moderation_status as enum ('pending','approved','rejected','reported');
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create table if not exists public.users (id uuid primary key default gen_random_uuid(), auth_user_id uuid unique, role public.user_role not null default 'SURVIVOR', victim_token text unique, phone_e164 text unique, display_name text, state text, district text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.identity_vault (user_id uuid primary key references public.users(id) on delete cascade, legal_name text, phone_e164 text, address jsonb, encrypted_metadata jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cases (id uuid primary key default gen_random_uuid(), docket text unique not null, victim_token text not null references public.users(victim_token), registered_phone_e164 text not null, case_type text, registration_date date, state text, district text, incident_date date, fir_status text, investigation_status text, chargesheet_status text, current_stage text, next_hearing_date date, hearing_count int default 0, adjournment_count int default 0, compensation_status text, compensation_amount_approved numeric, compensation_amount_received numeric, protection_status text, relocation_status text, legal_aid_status text, rehabilitation_status text, preferred_language text default 'en', is_synthetic boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.case_events (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, event_type text not null, label text not null, event_date timestamptz not null default now(), metadata jsonb, created_at timestamptz not null default now());
create table if not exists public.case_assignments (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, counsellor_user_id uuid not null references public.users(id), assigned_at timestamptz not null default now(), unassigned_at timestamptz);
create table if not exists public.consents (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, monitoring boolean not null, voice_analysis boolean not null default false, text_analysis boolean not null default false, behavioural_signals boolean not null default false, voice_consent boolean not null default false, version text not null, granted_at timestamptz not null default now(), revoked_at timestamptz);
create table if not exists public.monitoring_profiles (user_id uuid primary key references public.users(id) on delete cascade, state public.monitoring_state not null default 'active', paused_until timestamptz, changed_reason text, updated_at timestamptz not null default now());
create table if not exists public.wellbeing_observations (id uuid primary key default gen_random_uuid(), victim_token text not null, user_id uuid references public.users(id), mood smallint, sleep smallint, perceived_safety smallint, daily_functioning smallint, social_connectedness smallint, emotional_state jsonb, analytical_state text not null default 'insufficient_evidence', observed_at timestamptz not null default now());
create table if not exists public.text_signals (id uuid primary key default gen_random_uuid(), observation_id uuid references public.wellbeing_observations(id), victim_token text not null, consent_id uuid references public.consents(id), text_hash text, signals jsonb not null default '{}', crisis boolean not null default false, model_name text, model_version text, pipeline_version text, confidence numeric, created_at timestamptz not null default now());
create table if not exists public.voice_signals (id uuid primary key default gen_random_uuid(), observation_id uuid references public.wellbeing_observations(id), victim_token text not null, storage_path text, mime_type text, duration_seconds numeric, transcript text, features jsonb, model_name text, model_version text, created_at timestamptz not null default now(), purge_after timestamptz);
create table if not exists public.engagement_signals (id uuid primary key default gen_random_uuid(), victim_token text not null, signal_type text not null, value jsonb, observed_at timestamptz not null default now());
create table if not exists public.baselines (id uuid primary key default gen_random_uuid(), victim_token text not null, window_start timestamptz, window_end timestamptz, values jsonb not null, confidence numeric, model_version text, created_at timestamptz not null default now());
create table if not exists public.distress_scores (id uuid primary key default gen_random_uuid(), victim_token text not null, score numeric check(score between 0 and 100), confidence numeric, source_window tstzrange, contributing_factors jsonb, model_name text, model_version text, pipeline_version text, created_at timestamptz not null default now());
create table if not exists public.recovery_scores (id uuid primary key default gen_random_uuid(), victim_token text not null, score numeric check(score between 0 and 100), confidence numeric, source_window tstzrange, contributing_factors jsonb, model_name text, model_version text, pipeline_version text, created_at timestamptz not null default now());
create table if not exists public.risk_forecasts (id uuid primary key default gen_random_uuid(), victim_token text not null, escalation_probability numeric, uncertainty numeric, horizon_hours int, model_version text, created_at timestamptz not null default now());
create table if not exists public.alerts (id uuid primary key default gen_random_uuid(), case_id uuid references public.cases(id), victim_token text not null, priority public.priority_level not null, severity text, confidence numeric, reason text, contributing_factors jsonb, status public.alert_status not null default 'NEW', assigned_to uuid references public.users(id), resolution text, dedupe_key text unique, created_at timestamptz not null default now(), acknowledged_at timestamptz, assigned_at timestamptz, resolved_at timestamptz, last_seen_at timestamptz);
create table if not exists public.priority_records (id uuid primary key default gen_random_uuid(), alert_id uuid references public.alerts(id), priority public.priority_level, rationale jsonb, created_at timestamptz not null default now());
create table if not exists public.interventions (id uuid primary key default gen_random_uuid(), victim_token text not null, case_id uuid references public.cases(id), type text not null, initiated_by uuid references public.users(id), status text, metadata jsonb, started_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists public.intervention_feedback (id uuid primary key default gen_random_uuid(), intervention_id uuid references public.interventions(id) on delete cascade, user_id uuid references public.users(id), completed boolean, rating smallint, note text, created_at timestamptz not null default now());
create table if not exists public.follow_ups (id uuid primary key default gen_random_uuid(), case_id uuid references public.cases(id), counsellor_id uuid references public.users(id), due_at timestamptz, status text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.trusted_contacts (id uuid primary key default gen_random_uuid(), user_id uuid references public.users(id) on delete cascade, name text not null, phone_e164 text not null, consent_to_contact boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.safe_circle_events (id uuid primary key default gen_random_uuid(), trusted_contact_id uuid references public.trusted_contacts(id), event_type text, payload jsonb, created_at timestamptz not null default now());
create table if not exists public.support_resources (id uuid primary key default gen_random_uuid(), name text not null, service_type text, state text, district text, languages text[], availability text, phone text, metadata jsonb, created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references public.users(id) on delete cascade, channel text not null, category text, title text, body text, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.users(id), actor_role public.user_role, action text not null, resource_type text, resource_id text, request_id text, ip_hash text, metadata jsonb, created_at timestamptz not null default now());
create table if not exists public.community_posts (id uuid primary key default gen_random_uuid(), author_user_id uuid references public.users(id), body text not null, language text, moderation_status public.moderation_status not null default 'pending', created_at timestamptz not null default now());
create table if not exists public.community_moderation (id uuid primary key default gen_random_uuid(), post_id uuid references public.community_posts(id) on delete cascade, moderator_id uuid references public.users(id), action text, reason text, created_at timestamptz not null default now());
create index if not exists cases_district_idx on public.cases(district); create index if not exists cases_victim_idx on public.cases(victim_token); create index if not exists events_case_date_idx on public.case_events(case_id,event_date desc); create index if not exists distress_victim_date_idx on public.distress_scores(victim_token,created_at desc); create index if not exists alerts_status_priority_idx on public.alerts(status,priority); create index if not exists audit_created_idx on public.audit_logs(created_at desc);
create or replace view public.admin_operational_summary as select c.state,c.district,count(distinct c.id) case_count,count(a.id) alert_count from public.cases c left join public.alerts a on a.case_id=c.id and a.status in ('NEW','ACKNOWLEDGED','ASSIGNED') group by c.state,c.district;
create trigger users_updated before update on public.users for each row execute function public.touch_updated_at(); create trigger cases_updated before update on public.cases for each row execute function public.touch_updated_at();
alter table public.users enable row level security; alter table public.cases enable row level security; alter table public.wellbeing_observations enable row level security; alter table public.consents enable row level security; alter table public.trusted_contacts enable row level security; alter table public.notifications enable row level security;
-- Backend uses the service key after enforcing RBAC. Direct client access is intentionally denied by default.
create policy "no direct client access users" on public.users for all using (false) with check (false); create policy "no direct client access cases" on public.cases for all using (false) with check (false); create policy "no direct client access wellbeing" on public.wellbeing_observations for all using (false) with check (false); create policy "no direct client access consents" on public.consents for all using (false) with check (false); create policy "no direct client access contacts" on public.trusted_contacts for all using (false) with check (false); create policy "no direct client access notifications" on public.notifications for all using (false) with check (false);
